content.text:
{
  "name": "GigE Vision工业相机",
  "name_en": "GigE Vision industrial camera",
  "manufacturer": "Daheng Imaging",
  "description": "这是一类通过千兆以太网进行通信和图像传输的工业数字相机，可输出原始或彩色图像数据。实验室中常用于显微成像、机器视觉、自动化检测和各类需要远距离稳定图像采集的实验平台。",
  "description_en": "This is an industrial digital camera that communicates and streams image data over Gigabit Ethernet. It can provide raw or color image data and is commonly used in laboratories for microscopy, machine vision, automated inspection, and other setups requiring stable image acquisition over longer cable distances.",
  "actions": [
    {
      "action_name": "update_device_list",
      "description": "扫描并更新当前可发现的GigE Vision相机列表。",
      "description_en": "Scan for and refresh the list of currently discoverable GigE Vision cameras."
    },
    {
      "action_name": "update_all_device_list",
      "description": "扫描并更新所有可发现的相机设备列表。",
      "description_en": "Scan for and refresh the list of all discoverable camera devices."
    },
    {
      "action_name": "get_device_number",
      "description": "获取当前检测到的相机数量。",
      "description_en": "Get the number of currently detected cameras."
    },
    {
      "action_name": "get_device_info",
      "description": "获取指定相机的设备信息。",
      "description_en": "Get device information for a specified camera."
    },
    {
      "action_name": "open_device_by_index",
      "description": "按设备索引打开相机连接。",
      "description_en": "Open a camera connection by device index."
    },
    {
      "action_name": "open_device_by_sn",
      "description": "按序列号打开相机连接。",
      "description_en": "Open a camera connection by serial number."
    },
    {
      "action_name": "open_device_by_user_id",
      "description": "按用户自定义ID打开相机连接。",
      "description_en": "Open a camera connection by user-defined ID."
    },
    {
      "action_name": "open_device_by_ip",
      "description": "按IP地址打开相机连接。",
      "description_en": "Open a camera connection by IP address."
    },
    {
      "action_name": "open_device_by_mac",
      "description": "按MAC地址打开相机连接。",
      "description_en": "Open a camera connection by MAC address."
    }
  ],
  "tag_hints": [
    "GigE Vision",
    "industrial camera",
    "machine vision imaging",
    "microscopy imaging",
    "Ethernet image acquisition",
    "raw image capture",
    "color image capture"
  ]
}

